'use strict';
(()=>{const entry=document.querySelector('#hub-open');entry.textContent='← 모험 허브';const dialog=document.querySelector('#hub-dialog'),features=document.querySelector('#hub-features');
// Feature registry: new destinations can be added without changing the hub layout.
const sections=[{id:'books-open',key:'books',tag:'영구 해금 · 자유 조합',title:'전투 교본',text:'골드로 배우는 새로운 전술.\n캐릭터마다 세 가지 특성을 조합하세요.',action:'교본 펼치기',ready:true},{id:'vault-open',key:'vault',tag:'고블린의 초대',title:'고블린 금고',text:'1,000골드로 여는 행운.\n고블린 왕의 금고를 찾아보세요.',action:'금고 열기',ready:true},{id:'fusion-open',key:'fusion',tag:'보스의 힘',title:'레이드 융합',text:'토벌 보상을 장비에 더하고\n실제 전투력을 높이세요.',action:'융합 보관함',ready:true},{id:'ranking-open',key:'ranking',tag:'기록의 전당',title:'원정대 랭킹',text:'최고 돌파와 전투력.\n우리 원정대는 어디까지 왔을까?',action:'랭킹 보기',ready:true},{key:'hunt',tag:'함께하는 전투',title:'같이 사냥하기',text:'동료와 함께 필드를 누비는\n새로운 사냥을 준비하고 있어요.',action:'준비 중',ready:false},{id:'raid-open',key:'raid',tag:'함께하는 도전',title:'같이 레이드하기',text:'숫자 4자리 코드로 모여\n폐광의 거신을 함께 토벌하세요.',action:'레이드 입장',ready:true}];
const art=key=>key==='books'?'<path d="M25 25h35l12 8 12-8h35v60H84l-12 8-12-8H25ZM72 33v60M35 40h20m-20 13h20m32-13h20m-20 13h20"/>':key==='vault'?'<path d="M28 48h88v39H28Zm0 0 10-24h68l10 24M43 25v61m57-61v61M28 60h88"/><path class="gold" d="M64 49h16v22H64Zm5 7v8M54 14l6-5m24 5-6-5"/>':key==='fusion'?'<path class="gold" d="m72 17 27 31-27 40-27-40Z"/><path d="m45 48 27 10 27-10M72 17v71M28 30l8 8m72-8-8 8M27 79l11-5m79 5-11-5"/>':key==='ranking'?'<path d="M60 82V51h24v31M28 82V66h24v16M92 82V39h24v43"/><path class="gold" d="m72 16 5 10 11 2-8 8 2 11-10-5-10 5 2-11-8-8 11-2Z"/><path d="M18 85h108"/>':key==='hunt'?'<path d="m15 82 25-40 25 40M68 82l29-56 29 56M34 82V65m64 17V58"/><path class="gold" d="M52 75h25m-12-8v16m-12 9h25"/><circle cx="65" cy="56" r="6"/>':'<path d="m30 85 7-35 13-16 10 17 12-29 12 29 10-17 13 16 7 35Z"/><path class="gold" d="m52 64 10 5m30-5-10 5M66 82h12"/><path d="M17 91h110"/>';
features.innerHTML=sections.map(f=>`<button ${f.id?`id="${f.id}"`:''} class="hub-card hub-${f.key}" ${f.ready?'':'disabled'}><span class="hub-card-art" aria-hidden="true"><svg viewBox="0 0 144 106">${art(f.key)}</svg></span><span class="hub-card-copy"><small>${f.tag}</small><strong>${f.title}</strong><span>${f.text.replace('\n','<br>')}</span></span><span class="hub-card-action">${f.action}<b>${f.ready?'↗':'잠금'}</b></span></button>`).join('');
// Ranking's script binds before this file; its trigger is relayed through the existing event.
document.querySelector('#ranking-open').onclick=()=>{dialog.close();document.dispatchEvent(new Event('rpg:ranking-open'));};
document.querySelector('#raid-open').onclick=()=>{dialog.close();document.dispatchEvent(new Event('rpg:raid-open'));};
document.querySelector('#books-open').onclick=()=>{dialog.close();document.dispatchEvent(new Event('rpg:books-open'));};
document.querySelector('#vault-open').onclick=()=>{dialog.close();document.dispatchEvent(new Event('rpg:vault-open'));};
document.querySelector('#fusion-open').onclick=()=>{dialog.close();document.dispatchEvent(new Event('rpg:fusion-open'));};
function sync(){const api=window.RPG_ACCOUNT_UI,profile=api?.expedition?.profile;document.querySelector('#hub-identity').textContent=profile?profile.name+' 원정대':api?.account?.user?'원정대 이름을 설정해 주세요':'게스트 모험가';document.querySelector('#hub-save-status').textContent=api?.auto?.owner?(api.auto.blocked?'저장 확인이 필요해요. 계정 관리에서 확인하세요.':'구글 연결됨 · 클라우드 자동 저장 중'):api?.account?.user?'구글 연결됨 · 계정 관리에서 이어 할 저장을 선택하세요.':'이 기기에 저장 중 · 구글 연결로 이어 하기';}
function open(){sync();window.RPG_ACCOUNT_BRIDGE.pause(true);if(!dialog.open)dialog.showModal();}
document.addEventListener('rpg:hub-open',open);document.querySelector('#hub-settings').onclick=()=>{dialog.close();document.dispatchEvent(new Event('rpg:settings-open'));};document.querySelector('#hub-solo').onclick=()=>{dialog.close();const api=window.RPG_ACCOUNT_UI;if(api?.account?.user)api.continue();else document.dispatchEvent(new Event('rpg:start'));};document.querySelector('#hub-open').onclick=open;document.querySelector('#hub-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>window.RPG_ACCOUNT_BRIDGE.pause(false));document.querySelector('#account-open').addEventListener('click',()=>dialog.close(),{capture:true});document.addEventListener('rpg:account-render',sync);
})();
